+                const timer = setTimeout(
+                    () => reject(new ActualApiTimeoutError(operation, timeoutMs)),
+                    timeoutMs
+                );
+                callback().then(
+                    (val) => {
+                        clearTimeout(timer);
+                        resolve(val);
+                    },
+                    (err) => {
+                        clearTimeout(timer);
+                        reject(err);
+                    }
