-        console.log = createConsoleInterceptor(this.logger, originalLog);
-        console.info = createConsoleInterceptor(this.logger, originalInfo);
-        console.debug = createConsoleInterceptor(this.logger, originalDebug);
-        console.warn = createConsoleInterceptor(this.logger, originalWarn);
-
-        return () => {
-            console.log = originalLog;
-            console.info = originalInfo;
-            console.debug = originalDebug;
-            console.warn = originalWarn;
-        };
+        // Re-entrant patching with depth tracking
+        if ((this as any)._consolePatchDepth === undefined) {
+            (this as any)._consolePatchDepth = 0;
+        }
+        if ((this as any)._originalConsole === undefined) {
+            (this as any)._originalConsole = null as
+                | null
+                | { log: typeof console.log; info: typeof console.info; debug: typeof console.debug; warn: typeof console.warn };
+        }
+        if ((this as any)._consolePatchDepth === 0) {
+            (this as any)._originalConsole = {
+                log: console.log,
+                info: console.info,
+                debug: console.debug,
+                warn: console.warn,
+            };
+            console.log = createConsoleInterceptor(this.logger, console.log);
+            console.info = createConsoleInterceptor(this.logger, console.info);
+            console.debug = createConsoleInterceptor(this.logger, console.debug);
+            console.warn = createConsoleInterceptor(this.logger, console.warn);
+        }
+        (this as any)._consolePatchDepth++;
+
+        return () => {
+            (this as any)._consolePatchDepth--;
+            if ((this as any)._consolePatchDepth === 0 && (this as any)._originalConsole) {
+                const orig = (this as any)._originalConsole;
+                console.log = orig.log;
+                console.info = orig.info;
+                console.debug = orig.debug;
+                console.warn = orig.warn;
+                (this as any)._originalConsole = null;
