// At the top of src/utils/PayeeTransformer.ts, add:
import fs from 'fs/promises';
import path from 'node:path';
import { DEFAULT_DATA_DIR } from './shared.js';

    // Replace the existing getAvailableModels method with:
    private async getAvailableModels(): Promise<Array<string>> {
        if (this.availableModels) return this.availableModels;
        const cachePath = path.join(DEFAULT_DATA_DIR, 'openai-model-cache.json');
        const ttlMs = 24 * 60 * 60 * 1000;
        try {
            const raw = await fs.readFile(cachePath, 'utf8');
            const cached = JSON.parse(raw) as { fetchedAt: number; models: string[] };
            if (Array.isArray(cached.models) && Date.now() - (cached.fetchedAt ?? 0) < ttlMs) {
                this.availableModels = cached.models;
                return this.availableModels;
            }
        } catch {
            // cache miss/invalid -> refresh
        }
        const response = await this.openai.models.list();
        this.availableModels = response.data.map((m) => m.id);
        try {
            await fs.mkdir(DEFAULT_DATA_DIR, { recursive: true });
            await fs.writeFile(
                cachePath,
                JSON.stringify({ fetchedAt: Date.now(), models: this.availableModels }, null, 2),
                'utf8'
            );
        } catch {
            // best-effort cache write
        }
        return this.availableModels;
    }
```

</details>

